// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 t, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp, "unlockTime must be clamped to at least current time");
    }
}
